#!/usr/bin/env ruby
# frozen_string_literal: true

# DX helpers derived from the oracle: for a compound component (`Table` with `TableHeader`, `TableRow`...), the Phlex
# root yields itself and exposes one helper per nested part, so views can write
#
#   render Chadcn::Table.new do |table|
#     table.header { table.row { table.head { "Name" } } }
#   end
#
# instead of spelling out `render Chadcn::Table::Header.new`. The helpers are SUGAR: `root.header(**attrs, &block)` is
# exactly `render Root::Header.new(**attrs), &block`, generated by the namespace's `Base` (see ShadcnLayout::NAMESPACE), never hand-written.
#
#   ruby .claude/scripts/shadcn/spec_helpers.rb --all                  # append/refresh the derived section in every spec
#   ruby .claude/scripts/shadcn/spec_helpers.rb --component table      # one spec
#   ruby .claude/scripts/shadcn/spec_helpers.rb --component table --print   # print the helper list (JSON), change nothing
#   ruby .claude/scripts/shadcn/spec_helpers.rb --all --check          # exit 1 when a spec is missing or has a stale section
#
# Naming rule (single source): strip the root prefix once from the React export and snake_case the rest
# (`TableHead` -> `head`, `DropdownMenuCheckboxItem` -> `checkbox_item`, `SelectScrollUpButton` -> `scroll_up_button`).
# Idempotent: the section lives between <!-- spec_helpers:begin --> and <!-- spec_helpers:end -->.

require_relative "layout"
require "json"
require "optparse"
require "phlex"

opts = { oracle: ShadcnLayout::ORACLE_DIR, specs: ShadcnLayout::SPECS_DIR }
OptionParser.new do |o|
  o.on("--oracle DIR") { |v| opts[:oracle] = v }
  o.on("--specs DIR") { |v| opts[:specs] = v }
  o.on("--component NAME") { |v| opts[:component] = v }
  o.on("--all") { opts[:all] = true }
  o.on("--print") { opts[:print] = true }
  o.on("--check") { opts[:check] = true }
end.parse!

BEGIN_MARK = "<!-- spec_helpers:begin -->"
END_MARK = "<!-- spec_helpers:end -->"
# Phlex defines its element methods in included modules, so ask for inherited ones and subtract what every Object has.
HTML_ELEMENTS = (Phlex::HTML::StandardElements.public_instance_methods + Phlex::HTML::VoidElements.public_instance_methods).to_set
PHLEX_API = (Phlex::HTML.public_instance_methods - Object.public_instance_methods - HTML_ELEMENTS.to_a).to_set
OBJECT_METHODS = Object.public_instance_methods.to_set

def snake(str) = str.gsub(/([a-z\d])([A-Z])/, '\1_\2').gsub(/([A-Z]+)([A-Z][a-z])/, '\1_\2').downcase

# [{ part:, helper:, react: }] for a manifest; nil when the root is not an exported component
def helpers_for(manifest)
  root = ShadcnLayout.root_class_name(manifest["name"])
  exports = manifest["exports"].select { |e| e.match?(/\A[A-Z]/) }
  return nil unless exports.include?(root)

  # Every other capitalized export of the file is a part. The root prefix is stripped once when present
  # (`TableHead` -> `Head`); an export without the prefix (`ScrollBar` in scroll-area) keeps its full name.
  exports.reject { |e| e == root }.map do |e|
    short = e.start_with?(root) ? e.delete_prefix(root) : e
    { react: e, part: short, helper: snake(short) }
  end
end

def collisions(list)
  list.filter_map do |h|
    kind = if OBJECT_METHODS.include?(h[:helper].to_sym) then "ruby-core"
           elsif PHLEX_API.include?(h[:helper].to_sym) then "phlex-api"
           elsif HTML_ELEMENTS.include?(h[:helper].to_sym) then "phlex-element"
           end
    h.merge(kind: kind) if kind
  end
end

def section(manifest, list)
  root = ShadcnLayout.root_class_name(manifest["name"])
  var = snake(root)
  rows = list.map { |h| "| `#{var}.#{h[:helper]}` | `#{root}::#{h[:part]}` | `#{h[:react]}` |" }
  col = collisions(list)
  notes = []
  notes << "Names that shadow a Phlex HTML element inside `#{root}`'s OWN `view_template` (use `tag(:#{col.first[:helper]})` there, never the bare method): #{col.select { |c| c[:kind] == 'phlex-element' }.map { |c| "`#{c[:helper]}`" }.join(', ')}." if col.any? { |c| c[:kind] == "phlex-element" }
  notes << "RESERVED: #{col.select { |c| %w[ruby-core phlex-api].include?(c[:kind]) }.map { |c| "`#{c[:helper]}`" }.join(', ')} collides with a Ruby core / Phlex API method (it would break rendering): the part needs an explicit alias, tell the orchestrator." if col.any? { |c| %w[ruby-core phlex-api].include?(c[:kind]) }
  <<~MD.strip
    #{BEGIN_MARK}
    ## DX helpers (derived from the oracle, do not edit)

    `#{ShadcnLayout::NAMESPACE}::#{root}` MUST `yield self` from `view_template`; `#{ShadcnLayout::NAMESPACE}::Base` generates one helper per nested part (`const_added`), each exactly `render #{root}::<Part>.new(**attrs), &block`. The helpers are sugar: the nested classes stay the canonical API (scenarios, tests and the parity harness use them), and fully qualified calls (`render #{ShadcnLayout::NAMESPACE}::#{root}::Content.new`) stay valid.

    | helper | part class | React export |
    |---|---|---|
    #{rows.join("\n")}
    #{notes.map { |n| "\n#{n}" }.join}

    Acceptance (unit test): every row exists as a public method on the root instance and renders the same HTML as the explicit class call; no helper is defined by hand.
    #{END_MARK}
  MD
end

def apply(spec, text)
  if spec.include?(BEGIN_MARK)
    spec.sub(/#{Regexp.escape(BEGIN_MARK)}.*?#{Regexp.escape(END_MARK)}/m) { text }
  elsif (i = spec.index(/^## Dependencies/))
    spec.insert(i, "#{text}\n\n")
  else
    "#{spec.rstrip}\n\n#{text}\n"
  end
end

names = opts[:all] ? Dir[File.join(opts[:specs], "*.md")].map { |f| File.basename(f, ".md") }.sort : Array(opts[:component])
abort("usage: --component NAME | --all") if names.empty?

report = { updated: [], unchanged: [], no_parts: [], stale: [], collisions: {} }
names.each do |name|
  mf = File.join(opts[:oracle], "manifest", "#{name}.json")
  next unless File.exist?(mf)

  manifest = JSON.parse(File.read(mf))
  list = helpers_for(manifest)
  if list.nil? || list.empty?
    report[:no_parts] << name
    next
  end
  report[:collisions][name] = collisions(list).map { |c| "#{c[:helper]}(#{c[:kind]})" } if collisions(list).any?

  if opts[:print]
    puts JSON.pretty_generate(component: name, root: ShadcnLayout.root_constant(manifest["name"]), helpers: list.map { |h| h[:helper] }, parts: list)
    next
  end
  file = File.join(opts[:specs], "#{name}.md")
  next report[:stale] << name unless File.exist?(file)

  current = File.read(file)
  updated = apply(current.dup, section(manifest, list))
  if updated == current then report[:unchanged] << name
  elsif opts[:check] then report[:stale] << name
  else
    File.write(file, updated)
    report[:updated] << name
  end
end

unless opts[:print]
  puts JSON.pretty_generate(report.merge(pass: report[:stale].empty?))
  exit(report[:stale].empty? ? 0 : 1)
end
